INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4273318, 617447, 51793, '<td valign="top">This image lacks the lighting needed to make this stand out. I''m thinking that you might also need to back away from the subject a bit to try and gain more focus on the entire image. <br/> <br/>This is a weird layout as some of the pens are in the screen and some are out. You''re shadows are too strong too, this is caused by the lack of light on the subject. Good luck with the challenge.</td>', 'This image lacks the lighting needed to make this stand out. I''m thinking that you might also need to back away from the subject a bit to try and gain more focus on the entire image.  This is a weird layout as some of the pens are in the screen and some are out. You''re shadows are too strong too, this is caused by the lack of light on the subject. Good luck with the challenge.', '2007-11-28 10:33:30.000000', NULL, 1),
(4273319, 617497, 33542, '<td valign="top">This is a little soft, imo, and doesn''t fit the theme terribly well.</td>', 'This is a little soft, imo, and doesn''t fit the theme terribly well.', '2007-11-28 10:34:17.000000', NULL, 1),
(4273324, 616824, 51793, '<td valign="top">your lighting is all worng here. It makes the image look really bad. Also I''m not sure if you did or not but it looks like you used the USM filter a bit too much.</td>', 'your lighting is all worng here. It makes the image look really bad. Also I''m not sure if you did or not but it looks like you used the USM filter a bit too much.', '2007-11-28 10:36:45.000000', NULL, 1),
(4273334, 617402, 85927, '<td valign="top">Too easy....  Maybe if the picture had more punch (more vivid colors or sharper), maybe....</td>', 'Too easy....  Maybe if the picture had more punch (more vivid colors or sharper), maybe....', '2007-11-28 10:41:04.000000', NULL, 1),
(4273337, 617335, 85927, '<td valign="top">"Alone in a crowd" is exactly what is depicted here....  I just feel that the subject does not stand out of the rest of the crowd (maybe beacause of teh shadows).  Nice but sad picture, I love it.</td>', '"Alone in a crowd" is exactly what is depicted here....  I just feel that the subject does not stand out of the rest of the crowd (maybe beacause of teh shadows).  Nice but sad picture, I love it.', '2007-11-28 10:45:26.000000', NULL, 1),
(4273340, 616824, 87097, '<td valign="top">Cool idea, I like it! I know there were a bunch of "independent inventions" with the same idea in this contest, but I like this one the best because you only differentiate the skittle with the S vs M. The other pictures make the skittle stand out by being a different color as well. I like the subtlety in this case.</td>', 'Cool idea, I like it! I know there were a bunch of "independent inventions" with the same idea in this contest, but I like this one the best because you only differentiate the skittle with the S vs M. The other pictures make the skittle stand out by being a different color as well. I like the subtlety in this case.', '2007-11-28 10:48:55.000000', NULL, 1),
