(4274144, 615712, 77543, '<td valign="top">soft focus</td>', 'soft focus', '2007-11-28 15:37:12.000000', NULL, 1),
(4274146, 616774, 77543, '<td valign="top">This is a very noisy image</td>', 'This is a very noisy image', '2007-11-28 15:38:14.000000', NULL, 1),
(4274148, 617439, 77543, '<td valign="top">If it wasn''t for the title I''d have very little idea what this was all about.</td>', 'If it wasn''t for the title I''d have very little idea what this was all about.', '2007-11-28 15:39:43.000000', NULL, 1),
(4274153, 615846, 77543, '<td valign="top">I don''t get any sense of her being "alone", neither do I see much of a crowd.</td>', 'I don''t get any sense of her being "alone", neither do I see much of a crowd.', '2007-11-28 15:40:30.000000', NULL, 1),
(4274156, 617143, 49321, '<td valign="top">Definately my favorite!! Great idea and execution!!</td>', 'Definately my favorite!! Great idea and execution!!', '2007-11-28 15:44:01.000000', NULL, 1),
(4274158, 615619, 77543, '<td valign="top">I don''t see how this conveys "alone in a crowd"</td>', 'I don''t see how this conveys "alone in a crowd"', '2007-11-28 15:46:52.000000', NULL, 1),
(4274159, 616408, 77543, '<td valign="top">It''s not clear who is meant to be "alone" in this crowd.</td>', 'It''s not clear who is meant to be "alone" in this crowd.', '2007-11-28 15:47:41.000000', NULL, 1),
(4274163, 617333, 77543, '<td valign="top">"Alone" - maybe but I see no "crowd".</td>', '"Alone" - maybe but I see no "crowd".', '2007-11-28 15:49:04.000000', NULL, 1),
(4274165, 617335, 77543, '<td valign="top">If you removed the top half of this image it would convey "alone in a crowd" much better. As it is I needed the title to work out what was going on.</td>', 'If you removed the top half of this image it would convey "alone in a crowd" much better. As it is I needed the title to work out what was going on.', '2007-11-28 15:51:33.000000', NULL, 1),
(4274166, 617406, 77543, '<td valign="top">What are the green objects in the background? They spoil the effect.</td>', 'What are the green objects in the background? They spoil the effect.', '2007-11-28 15:52:08.000000', NULL, 1),
(4274168, 616833, 77543, '<td valign="top">Where or what is the crowd? This just looks like a poor picture of a bird.</td>', 'Where or what is the crowd? This just looks like a poor picture of a bird.', '2007-11-28 15:53:50.000000', NULL, 1),
(4274169, 617325, 77543, '<td valign="top">Slightly overexposed but a good idea.</td>', 'Slightly overexposed but a good idea.', '2007-11-28 15:54:24.000000', NULL, 1),
(4274171, 616422, 77543, '<td valign="top">But she''s holding two drinks.</td>', 'But she''s holding two drinks.', '2007-11-28 15:55:50.000000', NULL, 1),
(4274174, 617022, 77543, '<td valign="top">but where''s the crowd?</td>', 'but where''s the crowd?', '2007-11-28 15:56:44.000000', NULL, 1),
(4274175, 617338, 66597, '<td valign="top">This would be so pretty if it weren''t totally overprocessed. Too much saturation and USM.</td>', 'This would be so pretty if it weren''t totally overprocessed. Too much saturation and USM.', '2007-11-28 15:56:45.000000', NULL, 1),
(4274176, 617266, 66597, '<td valign="top">Deb, this shows really well. Especially against the competition. I wish I could vote - would give you a high score. Hope it''s doing well for you, and voters aren''t turned off by the "icky dead fish" factor. Very cool. Nicely seen.</td>', 'Deb, this shows really well. Especially against the competition. I wish I could vote - would give you a high score. Hope it''s doing well for you, and voters aren''t turned off by the "icky dead fish" factor. Very cool. Nicely seen.', '2007-11-28 15:57:04.000000', NULL, 1),
(4274179, 617513, 77543, '<td valign="top">I can''t tell who is meant to be "alone" in this "crowd"</td>', 'I can''t tell who is meant to be "alone" in this "crowd"', '2007-11-28 15:57:33.000000', NULL, 1),
(4274181, 617336, 77543, '<td valign="top">Overexposed</td>', 'Overexposed', '2007-11-28 15:57:46.000000', NULL, 1),
