(4274188, 617402, 77543, '<td valign="top">The words around the edge should be one large "crowd" since it is "a" single crowd rather than "crowds" plural.<br/>Other than that pedantry the picture suffers from a lack of depth of field and the positioning of the paper in relation to the background looks slapdash.</td>', 'The words around the edge should be one large "crowd" since it is "a" single crowd rather than "crowds" plural.Other than that pedantry the picture suffers from a lack of depth of field and the positioning of the paper in relation to the background looks slapdash.', '2007-11-28 16:02:58.000000', NULL, 1),
(4274190, 617516, 77543, '<td valign="top">This is neat. How did you manage this with basic editing?</td>', 'This is neat. How did you manage this with basic editing?', '2007-11-28 16:05:06.000000', NULL, 1),
(4274194, 615579, 77543, '<td valign="top">I wonder if anyone else will comment on the title.</td>', 'I wonder if anyone else will comment on the title.', '2007-11-28 16:06:25.000000', NULL, 1),
