(4275870, 617363, 48086, '<td valign="top">good concept, but not long enough shutterspeed for me. now the traces of people are distracting. colors are nice, square crop works well here, but would like subject a bit more top and right, to get rid of distracting top right wall.</td>', 'good concept, but not long enough shutterspeed for me. now the traces of people are distracting. colors are nice, square crop works well here, but would like subject a bit more top and right, to get rid of distracting top right wall.', '2007-11-29 09:46:03.000000', NULL, 1),
(4275871, 616279, 10071, '<td valign="top">You had a good idea with this one.  I would have only colorized the bag and lady together and BW the rest.  This way your eye would not move around the photo so much.  Thereby concentrating your focus on the subject more.</td>', 'You had a good idea with this one.  I would have only colorized the bag and lady together and BW the rest.  This way your eye would not move around the photo so much.  Thereby concentrating your focus on the subject more.', '2007-11-29 09:46:54.000000', NULL, 1),
(4275872, 616824, 48086, '<td valign="top">like the border for once, colors are lackluster due to flat light. good composition, but would like a differently colored s to make more of a contrast with m&amp;ms.</td>', 'like the border for once, colors are lackluster due to flat light. good composition, but would like a differently colored s to make more of a contrast with m&ms.', '2007-11-29 09:47:04.000000', NULL, 1),
(4275873, 616633, 10071, '<td valign="top">I understand by the title but a better cropping would have punched up the image better.</td>', 'I understand by the title but a better cropping would have punched up the image better.', '2007-11-29 09:48:00.000000', NULL, 1),
(4275875, 616276, 48086, '<td valign="top">classic shot, shame about the flat brownish light as colors look muted. composition is lacking its not central its not thirds its akward.</td>', 'classic shot, shame about the flat brownish light as colors look muted. composition is lacking its not central its not thirds its akward.', '2007-11-29 09:48:36.000000', NULL, 1),
