INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4275888, 615855, 10071, '<td valign="top">Good Capture.</td>', 'Good Capture.', '2007-11-29 09:53:33.000000', NULL, 1),
(4275889, 616279, 24454, '<td valign="top">:)   Don''tcha just FEEL the aching in her tired little feet looking at this?  She looks quite content in her aloneness, doesn''t she?<br/> <br/>I like it!</td>', ':)   Don''tcha just FEEL the aching in her tired little feet looking at this?  She looks quite content in her aloneness, doesn''t she? I like it!', '2007-11-29 09:53:33.000000', NULL, 1),
(4275890, 615708, 48086, '<td valign="top">like the contrasting colors and setup. perhaps a tighter crop on top to get right of distracting elements.</td>', 'like the contrasting colors and setup. perhaps a tighter crop on top to get right of distracting elements.', '2007-11-29 09:54:00.000000', NULL, 1),
(4275894, 617058, 10071, '<td valign="top">Too many stuffy things.  The girl becomes lost in the photo.</td>', 'Too many stuffy things.  The girl becomes lost in the photo.', '2007-11-29 09:54:28.000000', NULL, 1),
(4275895, 615712, 24454, '<td valign="top">Awwwww. . . .I remember my Dad with that "alone in a crowd" look on his face.  It brings memories swirling around me.</td>', 'Awwwww. . . .I remember my Dad with that "alone in a crowd" look on his face.  It brings memories swirling around me.', '2007-11-29 09:54:35.000000', NULL, 1),
(4275900, 617204, 10071, '<td valign="top">Puts a smile on my face.   Like many other food and object photos in this challenge the idea seems common but to relate it to a human experience takes my vote up a notch.</td>', 'Puts a smile on my face.   Like many other food and object photos in this challenge the idea seems common but to relate it to a human experience takes my vote up a notch.', '2007-11-29 09:55:47.000000', NULL, 1),
(4275904, 617516, 10071, '<td valign="top">This is good. Creative and the lighting is well balanced.</td>', 'This is good. Creative and the lighting is well balanced.', '2007-11-29 09:56:39.000000', NULL, 1),
(4275909, 617497, 10071, '<td valign="top">This image shows off how we are as a Western Culture.  The iPod has moved our society into a different era - We must accept it.</td>', 'This image shows off how we are as a Western Culture.  The iPod has moved our society into a different era - We must accept it.', '2007-11-29 09:57:59.000000', NULL, 1),
(4275917, 617204, 33181, '<td valign="top">Neat Idea - It may be a little too much softening for my taste though.  Nice shot none the less</td>', 'Neat Idea - It may be a little too much softening for my taste though.  Nice shot none the less', '2007-11-29 10:05:27.000000', NULL, 1),
(4275920, 615708, 33181, '<td valign="top">The yellows and oranges on this seem to be oversaturated on my monitor</td>', 'The yellows and oranges on this seem to be oversaturated on my monitor', '2007-11-29 10:06:28.000000', NULL, 1),
(4275921, 617143, 33181, '<td valign="top">Cool image ... I think that you stuck the challenge idea well</td>', 'Cool image ... I think that you stuck the challenge idea well', '2007-11-29 10:07:06.000000', NULL, 1),
(4275924, 617391, 68586, '<td valign="top">Hmm .. I''ve gone backwards and forwards on my thoughts with this one, but I do like the picture. I love the tones and colours, the slightly sad look to the front of the car, and the almost surreal effect of this street vendor and his customers who look (to me at least) like they should all be on the beach, yet here they are in a busy street surrounded by poles and cables and a whole run down air to the area.<br/> <br/>In picture terms I think  ideally you would have moved the whole picture slightly to the right so we got to see the street vendor, (who i think is important to this picture) and lost the guy half in the picture (who isn''t important to it).</td>', 'Hmm .. I''ve gone backwards and forwards on my thoughts with this one, but I do like the picture. I love the tones and colours, the slightly sad look to the front of the car, and the almost surreal effect of this street vendor and his customers who look (to me at least) like they should all be on the beach, yet here they are in a busy street surrounded by poles and cables and a whole run down air to the area. In picture terms I think  ideally you would have moved the whole picture slightly to the right so we got to see the street vendor, (who i think is important to this picture) and lost the guy half in the picture (who isn''t important to it).', '2007-11-29 10:07:46.000000', NULL, 1),
(4275927, 617391, 33181, '<td valign="top">nice image ... good symbolism with the title.  I love the girl looking at the camera ...</td>', 'nice image ... good symbolism with the title.  I love the girl looking at the camera ...', '2007-11-29 10:08:49.000000', NULL, 1),
(4275929, 617336, 33181, '<td valign="top">Seems to be just on the edge of being blown.  The colors do not have a lot of pop to them</td>', 'Seems to be just on the edge of being blown.  The colors do not have a lot of pop to them', '2007-11-29 10:10:13.000000', NULL, 1),
(4275931, 617367, 33181, '<td valign="top">Kinda snapshotty .  Composition is ok though</td>', 'Kinda snapshotty .  Composition is ok though', '2007-11-29 10:11:19.000000', NULL, 1),
(4275943, 616035, 33181, '<td valign="top">Where do I start ... (I do bellydance performance as part of my service offerings and have over 30K bellydance images in my inventory SO... I might see some things that some others may not ... Hang on !)<br/> <br/>Overall:  Not a bad capture - although I may not have used this one ... It is just about a bun shot (with the skirt flying up)  Luckily she has on bike shorts (I think).  The dancer is in a good position (strong hands food foot position decent posture) This looks to be a difficult lighting situation (as many hoflas are) but I would have liked to see more of an exposure (accept some motion blur in exchange for better illumination)- Looks like you have a full stop at least that you could have played with.  That would have helped separate her hair a bit. Watch your white balance.<br/> <br/>Not a bad capture in a difficult setting</td>', 'Where do I start ... (I do bellydance performance as part of my service offerings and have over 30K bellydance images in my inventory SO... I might see some things that some others may not ... Hang on !) Overall:  Not a bad capture - although I may not have used this one ... It is just about a bun shot (with the skirt flying up)  Luckily she has on bike shorts (I think).  The dancer is in a good position (strong hands food foot position decent posture) This looks to be a difficult lighting situation (as many hoflas are) but I would have liked to see more of an exposure (accept some motion blur in exchange for better illumination)- Looks like you have a full stop at least that you could have played with.  That would have helped separate her hair a bit. Watch your white balance. Not a bad capture in a difficult setting', '2007-11-29 10:22:10.000000', NULL, 1),
(4275945, 616633, 33181, '<td valign="top">Ok croud shot but I would have liked to see an isolation on one of the people in the crowd</td>', 'Ok croud shot but I would have liked to see an isolation on one of the people in the crowd', '2007-11-29 10:23:13.000000', NULL, 1),
(4275946, 617516, 33181, '<td valign="top">well doe image ... but hosestly ... I have seen way too many glasses.  Dont get me wrong this is well done and I am giving it a 7 but the glass bit it getting a bit trite</td>', 'well doe image ... but hosestly ... I have seen way too many glasses.  Dont get me wrong this is well done and I am giving it a 7 but the glass bit it getting a bit trite', '2007-11-29 10:25:42.000000', NULL, 1),
(4275947, 617255, 33181, '<td valign="top">well done ... matches the challenge perfectly</td>', 'well done ... matches the challenge perfectly', '2007-11-29 10:26:15.000000', NULL, 1),
(4275954, 616774, 33181, '<td valign="top">I am just not feeling this ... it doesn''t have any pop to it ... the background is just a pixilated mass of pink blue and white looks like there may be noise issues ... but I cant really tell... Yyyyyeah .... I got nothin</td>', 'I am just not feeling this ... it doesn''t have any pop to it ... the background is just a pixilated mass of pink blue and white looks like there may be noise issues ... but I cant really tell... Yyyyyeah .... I got nothin', '2007-11-29 10:29:38.000000', NULL, 1),
