(4280830, 615619, 48697, '<td valign="top">The angle in this shot seems a bit awkward and I''m having a hard time making the connection that this shot envokes alone in a crowd. I do like the tone that was used.</td>', 'The angle in this shot seems a bit awkward and I''m having a hard time making the connection that this shot envokes alone in a crowd. I do like the tone that was used.', '2007-12-01 16:09:45.000000', NULL, 1),
(4280837, 616231, 48697, '<td valign="top">The lighting seems a bit harsh, probably b/c of the refective rappers and glossey plate that they sit upon.  Maybe diffusing the light and using a solid white non-reflective background might have given this a softer appearance.</td>', 'The lighting seems a bit harsh, probably b/c of the refective rappers and glossey plate that they sit upon.  Maybe diffusing the light and using a solid white non-reflective background might have given this a softer appearance.', '2007-12-01 16:12:56.000000', NULL, 1),
(4280840, 617196, 48697, '<td valign="top">I feel that the white foreground distracts in this photo.</td>', 'I feel that the white foreground distracts in this photo.', '2007-12-01 16:14:40.000000', NULL, 1),
(4280851, 617402, 48697, '<td valign="top">a clever, humerous take on the challenge but I believe that it has an appearance of being thrown together in a hurry.   I feel that the the focus is a bit off and that this might have been better compositionally if written in the center of the page so the edge of the paper would not be in the frame.</td>', 'a clever, humerous take on the challenge but I believe that it has an appearance of being thrown together in a hurry.   I feel that the the focus is a bit off and that this might have been better compositionally if written in the center of the page so the edge of the paper would not be in the frame.', '2007-12-01 16:19:13.000000', NULL, 1),
(4280854, 615935, 48697, '<td valign="top">Nice candid capture and the kid defintly looks alone in the crowd of craziness</td>', 'Nice candid capture and the kid defintly looks alone in the crowd of craziness', '2007-12-01 16:20:51.000000', NULL, 1),
(4280858, 617439, 48697, '<td valign="top">intresting abstract feel this this and I think it''s a creative angle for the challenge.</td>', 'intresting abstract feel this this and I think it''s a creative angle for the challenge.', '2007-12-01 16:22:29.000000', NULL, 1),
