(4287290, 617219, 2000, '<td valign="top">Nice idea, but I think you got a bit over exposed... the exposure makes the shot look very flat to me.</td>', 'Nice idea, but I think you got a bit over exposed... the exposure makes the shot look very flat to me.', '2007-12-04 00:02:24.000000', NULL, 1),
(4287295, 616774, 2000, '<td valign="top">Nice idea... I can see the message you''re shooting.  The fence and some of the other leaves, however, are too close in color to the blue ''subject''.</td>', 'Nice idea... I can see the message you''re shooting.  The fence and some of the other leaves, however, are too close in color to the blue ''subject''.', '2007-12-04 00:04:26.000000', NULL, 1),
(4287298, 616827, 2000, '<td valign="top">Focus, subject, and challenge are missed here... sorry.</td>', 'Focus, subject, and challenge are missed here... sorry.', '2007-12-04 00:05:27.000000', NULL, 1),
(4287300, 616178, 2000, '<td valign="top">I didn''t realize he looked the other way... that gets you a bonus point for teaching me something.</td>', 'I didn''t realize he looked the other way... that gets you a bonus point for teaching me something.', '2007-12-04 00:06:32.000000', NULL, 1),
(4287308, 616218, 2000, '<td valign="top">Emotional and physical takes on the challenge... this style looks very familiar to me.  Something in the focus isn''t feeling right here tho.</td>', 'Emotional and physical takes on the challenge... this style looks very familiar to me.  Something in the focus isn''t feeling right here tho.', '2007-12-04 00:09:02.000000', NULL, 1),
(4287313, 616852, 2000, '<td valign="top">This is a very nice portrait, and the little girl seems in her own little world.  But I would like to see a bit more of the surrounding people, just to enhance the crowd that she''s alone in.</td>', 'This is a very nice portrait, and the little girl seems in her own little world.  But I would like to see a bit more of the surrounding people, just to enhance the crowd that she''s alone in.', '2007-12-04 00:11:39.000000', NULL, 1),
(4287322, 617204, 2000, '<td valign="top">A lot of people went the M&amp;M route, and I like the different way you''ve done it.  Something about the lighting (they''re on a lightbox?) makes the M&amp;Ms look like the balls in a kids amusement.  8 for now.</td>', 'A lot of people went the M&M route, and I like the different way you''ve done it.  Something about the lighting (they''re on a lightbox?) makes the M&Ms look like the balls in a kids amusement.  8 for now.', '2007-12-04 00:14:49.000000', NULL, 1),
(4287330, 617408, 2000, '<td valign="top">Nearly perfect... The bowl looks like it should be centered in the frame to me.  But I like how you''ve made that poor green froot loop feel shunned.  9</td>', 'Nearly perfect... The bowl looks like it should be centered in the frame to me.  But I like how you''ve made that poor green froot loop feel shunned.  9', '2007-12-04 00:19:23.000000', NULL, 1),
(4287336, 617367, 2000, '<td valign="top">Try to keep your photos with one side at the maximum size whenever possible.  I see the file size was an issue, but smaller photos are harder to see.</td>', 'Try to keep your photos with one side at the maximum size whenever possible.  I see the file size was an issue, but smaller photos are harder to see.', '2007-12-04 00:21:25.000000', NULL, 1),
(4287345, 617409, 2000, '<td valign="top">I await the photo description to see what those other things are (or are they just rinsed M&amp;Ms?).  I like the vision and technique here.</td>', 'I await the photo description to see what those other things are (or are they just rinsed M&Ms?).  I like the vision and technique here.', '2007-12-04 00:24:25.000000', NULL, 1),
(4287359, 616833, 2000, '<td valign="top">Very nice idea, and a fortunate shot with the bird still enough to photograph.  Try to use the full dimensions allowed (640 on a side) to emphasize your work.</td>', 'Very nice idea, and a fortunate shot with the bird still enough to photograph.  Try to use the full dimensions allowed (640 on a side) to emphasize your work.', '2007-12-04 00:29:37.000000', NULL, 1),
(4287367, 617402, 2000, '<td valign="top">Sometimes nice to see a whatzit... but sometimes its better just to sit out a challenge too.  Don''t mean to be harsh.</td>', 'Sometimes nice to see a whatzit... but sometimes its better just to sit out a challenge too.  Don''t mean to be harsh.', '2007-12-04 00:33:46.000000', NULL, 1),
(4287369, 615619, 2000, '<td valign="top">I didn''t see the guy at first... the lighting makes him not stand out.  I''m not sure if that''s what you were going for, but it doesn''t really meet the challenge for me.</td>', 'I didn''t see the guy at first... the lighting makes him not stand out.  I''m not sure if that''s what you were going for, but it doesn''t really meet the challenge for me.', '2007-12-04 00:35:22.000000', NULL, 1),
(4287377, 616633, 2000, '<td valign="top">One of the few times this would work... but it definitely meets the challenge.  This is one of those photos you almost expect to see hanging in a coffee shop.</td>', 'One of the few times this would work... but it definitely meets the challenge.  This is one of those photos you almost expect to see hanging in a coffee shop.', '2007-12-04 00:39:06.000000', NULL, 1),
(4287549, 616218, 22301, '<td valign="top">I like it, a different take on the challenge. The repeating patterns broken y the lone man sets a stark aloneness.</td>', 'I like it, a different take on the challenge. The repeating patterns broken y the lone man sets a stark aloneness.', '2007-12-04 03:09:57.000000', NULL, 1),
(4287551, 616408, 22301, '<td valign="top">I hope this does really well, its what I want to see near the top. Great use of ambient light to separate the main subject. bump to ten</td>', 'I hope this does really well, its what I want to see near the top. Great use of ambient light to separate the main subject. bump to ten', '2007-12-04 03:11:36.000000', NULL, 1),
(4287552, 615549, 22301, '<td valign="top">Its funny I wouldn''t have thought to take a shot like this, but it works really well for me. the face is a little dark, but not bothering me. good luck.</td>', 'Its funny I wouldn''t have thought to take a shot like this, but it works really well for me. the face is a little dark, but not bothering me. good luck.', '2007-12-04 03:13:25.000000', NULL, 1),
(4287553, 617349, 22301, '<td valign="top">I hope this does well, I wish the frame was straight, but thats all I would change. I think I wish it was straight so you wouldn''t get marked down by other voters though, not because I think it makes a great difference in what I think of the photo. :)</td>', 'I hope this does well, I wish the frame was straight, but thats all I would change. I think I wish it was straight so you wouldn''t get marked down by other voters though, not because I think it makes a great difference in what I think of the photo. :)', '2007-12-04 03:15:21.000000', NULL, 1),
(4287554, 617493, 22301, '<td valign="top">great work with the white on white, and the pun got you bonus points. :)</td>', 'great work with the white on white, and the pun got you bonus points. :)', '2007-12-04 03:16:08.000000', NULL, 1),
(4287555, 616923, 22301, '<td valign="top">cool find, surprised it was needed to be validated. the foreground is a little dark, but still one of my top scorers.</td>', 'cool find, surprised it was needed to be validated. the foreground is a little dark, but still one of my top scorers.', '2007-12-04 03:17:34.000000', NULL, 1),
(4287556, 617437, 22301, '<td valign="top">great candid, I still get that look if I try and ice skate. :)</td>', 'great candid, I still get that look if I try and ice skate. :)', '2007-12-04 03:18:12.000000', NULL, 1),
(4287559, 617363, 22301, '<td valign="top">great color, enjoying the pastel hues.  the slow shutterspeed really sets the aloneness in motion.</td>', 'great color, enjoying the pastel hues.  the slow shutterspeed really sets the aloneness in motion.', '2007-12-04 03:20:05.000000', NULL, 1),
(4287560, 617143, 22301, '<td valign="top">nice hand held shot, I am guess around and 1/8 sec shutter. I may have cropped a little bit off the top, maybe just below the fan.</td>', 'nice hand held shot, I am guess around and 1/8 sec shutter. I may have cropped a little bit off the top, maybe just below the fan.', '2007-12-04 03:22:15.000000', NULL, 1),
(4287562, 616504, 22301, '<td valign="top">what an interesting perspective, good black and white conversion. I can''t decide if the baby really feels alone though but I like the shot too much to give it a low score. :)</td>', 'what an interesting perspective, good black and white conversion. I can''t decide if the baby really feels alone though but I like the shot too much to give it a low score. :)', '2007-12-04 03:24:05.000000', NULL, 1),
(4287569, 617244, 22301, '<td valign="top">tough call. on one hand its a beautiful shot and could grace any newspaper right on the front page. but I don''t think in victory you would feel alone, especially when being held up by the fans. hmmm. 7</td>', 'tough call. on one hand its a beautiful shot and could grace any newspaper right on the front page. but I don''t think in victory you would feel alone, especially when being held up by the fans. hmmm. 7', '2007-12-04 03:30:43.000000', NULL, 1),
(4287571, 616155, 22301, '<td valign="top">subtle but I hope it connects with the voters, I enjoy it so you got that going for you. :P<br/>nice idea to fit the challenge.</td>', 'subtle but I hope it connects with the voters, I enjoy it so you got that going for you. :Pnice idea to fit the challenge.', '2007-12-04 03:32:19.000000', NULL, 1),
(4287572, 617233, 22301, '<td valign="top">the idea is nice, but the lighting is really uneven and abit harsh like from a flash too far from the scene and not diffused at all. maybe try and shoot when available light was an option. or maybe you were just leaning over the scene and blocking the light? a good effort, but better light would have really made it shine. 6</td>', 'the idea is nice, but the lighting is really uneven and abit harsh like from a flash too far from the scene and not diffused at all. maybe try and shoot when available light was an option. or maybe you were just leaning over the scene and blocking the light? a good effort, but better light would have really made it shine. 6', '2007-12-04 03:35:37.000000', NULL, 1),
(4287574, 615624, 22301, '<td valign="top">I enjoy the candlelight''s civil disobedience</td>', 'I enjoy the candlelight''s civil disobedience', '2007-12-04 03:37:53.000000', NULL, 1),
(4287575, 616958, 22301, '<td valign="top">I think this needs a little bit more contrast, there is hardly any black in the photo. Maybe try a little S curve using a curves adjustment layer. Nice find though, he looks perplexed. :)</td>', 'I think this needs a little bit more contrast, there is hardly any black in the photo. Maybe try a little S curve using a curves adjustment layer. Nice find though, he looks perplexed. :)', '2007-12-04 03:41:02.000000', NULL, 1),
(4287577, 617204, 22301, '<td valign="top">I like the title, bonus point for you. :)<br/>I like how it seems to be lit from the top and bottom, one more bonus point for you. :) 8</td>', 'I like the title, bonus point for you. :)I like how it seems to be lit from the top and bottom, one more bonus point for you. :) 8', '2007-12-04 03:42:18.000000', NULL, 1),
(4287578, 616741, 22301, '<td valign="top">Nice candid, I may have cropped off the second deck to have the viewer focus on the fan.</td>', 'Nice candid, I may have cropped off the second deck to have the viewer focus on the fan.', '2007-12-04 03:43:42.000000', NULL, 1),
(4287582, 617516, 22301, '<td valign="top">I think I saw these guys hanging around in the FS. :P<br/>The backlighting is excellent, but this doesn''t really feel like a crowded situation for me, so I can''t give it the highest marks. 7</td>', 'I think I saw these guys hanging around in the FS. :PThe backlighting is excellent, but this doesn''t really feel like a crowded situation for me, so I can''t give it the highest marks. 7', '2007-12-04 03:49:08.000000', NULL, 1),
(4287583, 617255, 22301, '<td valign="top">I like this more i look at it, especially with all the heads cut off and everyone else standing up. double bump.</td>', 'I like this more i look at it, especially with all the heads cut off and everyone else standing up. double bump.', '2007-12-04 03:50:02.000000', NULL, 1),
(4287586, 617335, 22301, '<td valign="top">A little too much shadow to really see the subject for me.</td>', 'A little too much shadow to really see the subject for me.', '2007-12-04 03:55:57.000000', NULL, 1),
(4287587, 617342, 22301, '<td valign="top">I think this composition needs a little work, everything seems too crowded and the yarn is placed a little too much in the center. I think the image needs a little space, but the idea is there.</td>', 'I think this composition needs a little work, everything seems too crowded and the yarn is placed a little too much in the center. I think the image needs a little space, but the idea is there.', '2007-12-04 03:58:36.000000', NULL, 1),
(4287600, 617402, 22301, '<td valign="top">photo is a little dark, you can try using levels and move the middle and right lider to the left to brighten. I think this would have been more successful if you had made the words out of something like rocks, peas anything. just my two cents</td>', 'photo is a little dark, you can try using levels and move the middle and right lider to the left to brighten. I think this would have been more successful if you had made the words out of something like rocks, peas anything. just my two cents', '2007-12-04 05:07:17.000000', NULL, 1),
(4287602, 615619, 22301, '<td valign="top">if you have PS you might want to try this <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a> to get your images as large as they can with the most details save. For example your file size is 98 kb, but the max level 150 kb. This would have gotten rid of the small jagged edges in the fine details of your photograph. Hope this helps<br/>As a photo for this challenge it is also hard to give a high score for this photo because I don''t get the impression of a crowd.</td>', 'if you have PS you might want to try this tutorial to get your images as large as they can with the most details save. For example your file size is 98 kb, but the max level 150 kb. This would have gotten rid of the small jagged edges in the fine details of your photograph. Hope this helpsAs a photo for this challenge it is also hard to give a high score for this photo because I don''t get the impression of a crowd.', '2007-12-04 05:11:51.000000', NULL, 1),
(4287603, 617384, 22301, '<td valign="top">this would look good as an ad, but I think it is a little bit of a stretch to meet the challenge., i like the lighting though the model is evenly lit.</td>', 'this would look good as an ad, but I think it is a little bit of a stretch to meet the challenge., i like the lighting though the model is evenly lit.', '2007-12-04 05:13:16.000000', NULL, 1),
(4287604, 617060, 22301, '<td valign="top">a cute shot and the studio light is top notch, but I don''t get the impression she feels alone. I like Elmo''s expression over the snake. :)</td>', 'a cute shot and the studio light is top notch, but I don''t get the impression she feels alone. I like Elmo''s expression over the snake. :)', '2007-12-04 05:15:14.000000', NULL, 1),
(4287606, 616833, 22301, '<td valign="top">If you have any version of photoshop take a look at this <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a>. It will show you how to prepare your image for challenges and get your image to the 640 pixel 150 kb allowances. Your image is 480 pixel and only 38 kb. If you maximize your file size you will have smooth features around your bird and high contrast edges. Doing this will allow you to get a more accurate score as many people instantly knock off points for small photos and jagged edges thining it is oversharpened. Hope this helps. If you don''t have PS try to find a save as function that allows you to set your own file size to 150 kb.</td>', 'If you have any version of photoshop take a look at this tutorial. It will show you how to prepare your image for challenges and get your image to the 640 pixel 150 kb allowances. Your image is 480 pixel and only 38 kb. If you maximize your file size you will have smooth features around your bird and high contrast edges. Doing this will allow you to get a more accurate score as many people instantly knock off points for small photos and jagged edges thining it is oversharpened. Hope this helps. If you don''t have PS try to find a save as function that allows you to set your own file size to 150 kb.', '2007-12-04 05:21:02.000000', NULL, 1),
(4287610, 617406, 22301, '<td valign="top">i like the depth of Field to single out the redman. I think I would have tried not such a narrow crop.</td>', 'i like the depth of Field to single out the redman. I think I would have tried not such a narrow crop.', '2007-12-04 05:28:16.000000', NULL, 1),
(4287618, 616852, 22301, '<td valign="top">thats a nice exposure for a tough lighting situation. seems like a little bit of a stretch for the challenge, but I like the camera also pointed at her in the background.</td>', 'thats a nice exposure for a tough lighting situation. seems like a little bit of a stretch for the challenge, but I like the camera also pointed at her in the background.', '2007-12-04 05:36:29.000000', NULL, 1),
(4287619, 615712, 22301, '<td valign="top">She seems engaged in a conversation to me, but I am giving the benefit of the doubt. try to work on the focus abit, maybe steady yourself on a table or make sure the focus is locked before you click. 5</td>', 'She seems engaged in a conversation to me, but I am giving the benefit of the doubt. try to work on the focus abit, maybe steady yourself on a table or make sure the focus is locked before you click. 5', '2007-12-04 05:36:31.000000', NULL, 1),
(4287624, 617367, 22301, '<td valign="top">If you have photoshop, you should try to use the Save for Web feature, it will let you set the image file size and pixel size. Here is a <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a> on DPC to walk you through it. I hope this helps you.  I saw you got your image up to the max file size but had to make it small. This is because it still has exif data attached to it that tells you this was shot with a D80 and all your settings. What the Save for Web feature does is get rid of that data and allows  more of the file size to be used in image quality. Hope this helps</td>', 'If you have photoshop, you should try to use the Save for Web feature, it will let you set the image file size and pixel size. Here is a tutorial on DPC to walk you through it. I hope this helps you.  I saw you got your image up to the max file size but had to make it small. This is because it still has exif data attached to it that tells you this was shot with a D80 and all your settings. What the Save for Web feature does is get rid of that data and allows  more of the file size to be used in image quality. Hope this helps', '2007-12-04 05:45:13.000000', NULL, 1),
(4287625, 616774, 22301, '<td valign="top">Try using the Save For Web function in photoshop, from there you can set your image size to 640 pixels and the file size to as close to the 150 kb size limit. Here is a little DPC <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a> to help you through it.  Hope this helps you out.</td>', 'Try using the Save For Web function in photoshop, from there you can set your image size to 640 pixels and the file size to as close to the 150 kb size limit. Here is a little DPC tutorial to help you through it.  Hope this helps you out.', '2007-12-04 05:48:27.000000', NULL, 1),
(4287626, 617391, 22301, '<td valign="top">I think alot of voters will have a hard time connecting this image to the challenge. I think it has to do with the car and you are in Cuba, but I don''t see a crowd really, just a few other cars. 5</td>', 'I think alot of voters will have a hard time connecting this image to the challenge. I think it has to do with the car and you are in Cuba, but I don''t see a crowd really, just a few other cars. 5', '2007-12-04 05:50:57.000000', NULL, 1),
(4287628, 617411, 22301, '<td valign="top">The lighting is very well done, but I think it needs a better composition as the apple is in the center. I do like how you expanded on the apples and oranges theme though, a nice touch. :)</td>', 'The lighting is very well done, but I think it needs a better composition as the apple is in the center. I do like how you expanded on the apples and oranges theme though, a nice touch. :)', '2007-12-04 05:53:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4287629, 617447, 22301, '<td valign="top">I think including the edges of all the pencils would have helped your score. a good concept and way to find a different way to present the challenge theme.</td>', 'I think including the edges of all the pencils would have helped your score. a good concept and way to find a different way to present the challenge theme.', '2007-12-04 05:57:17.000000', NULL, 1),
(4287634, 616392, 22301, '<td valign="top">I hope this doe well, I wanted to find something like this but I must not believe in Santa as much as you and he never showed. :P</td>', 'I hope this doe well, I wanted to find something like this but I must not believe in Santa as much as you and he never showed. :P', '2007-12-04 06:05:14.000000', NULL, 1),
(4287636, 615935, 22301, '<td valign="top">I feel this boy''s pain! getting a bump up. I hope this is doing well for you.</td>', 'I feel this boy''s pain! getting a bump up. I hope this is doing well for you.', '2007-12-04 06:06:17.000000', NULL, 1),
(4287638, 616824, 22301, '<td valign="top">The lighting is a little flat, but a good idea.</td>', 'The lighting is a little flat, but a good idea.', '2007-12-04 06:06:27.000000', NULL, 1),
