(4288839, 617426, 22301, '<td valign="top">I like this high contrast black and white, it makes for a really good image on its own. But for an entry it doesn''t really connect for me. 5</td>', 'I like this high contrast black and white, it makes for a really good image on its own. But for an entry it doesn''t really connect for me. 5', '2007-12-04 17:12:49.000000', NULL, 1),
(4288840, 617363, 61267, '<td valign="top">You capture the theme perfectly with your photo. Nice use of shutter speed to create the scene.</td>', 'You capture the theme perfectly with your photo. Nice use of shutter speed to create the scene.', '2007-12-04 17:14:52.000000', NULL, 1),
(4288841, 617408, 22301, '<td valign="top">a good idea, the separated loop fits the challenge well. I think for many voters though, they will find the subject too ordinary for high votes.</td>', 'a good idea, the separated loop fits the challenge well. I think for many voters though, they will find the subject too ordinary for high votes.', '2007-12-04 17:15:23.000000', NULL, 1),
(4288844, 617439, 22301, '<td valign="top">is the blueberry the predator or prey, there are no witnesses...</td>', 'is the blueberry the predator or prey, there are no witnesses...', '2007-12-04 17:17:05.000000', NULL, 1),
(4288847, 617323, 22301, '<td valign="top">I like the scene, but it seems oversharpened  and the whites of the birds are too bright to me and seem unnatural. I like the composition though, particularly how the woman is framed between the trees and in mid-stride</td>', 'I like the scene, but it seems oversharpened  and the whites of the birds are too bright to me and seem unnatural. I like the composition though, particularly how the woman is framed between the trees and in mid-stride', '2007-12-04 17:19:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4288850, 617462, 22301, '<td valign="top">I like the wide angle with all the leaves, the image I think could be brightened up a little, its hard to make out the main subject''s face.</td>', 'I like the wide angle with all the leaves, the image I think could be brightened up a little, its hard to make out the main subject''s face.', '2007-12-04 17:21:21.000000', NULL, 1),
(4288858, 616633, 22301, '<td valign="top">I know that corner :) I like the red hand. it has some noise but doesn''t bother me. I think it would have been stronger if you had shot more of the people and less of the buildings to make the crowd fill the frame more.</td>', 'I know that corner :) I like the red hand. it has some noise but doesn''t bother me. I think it would have been stronger if you had shot more of the people and less of the buildings to make the crowd fill the frame more.', '2007-12-04 17:24:58.000000', NULL, 1),
(4288887, 617196, 22301, '<td valign="top">A nice winterly scene, but I wish it was larger. If you have PS you can look at this <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a> to get your image up to 640 pixels and 150 kb. Your image is 82 kb, which means you could get twice as many fine details smoothed out in the cattails. Hope this helps, I like your image, just a little small.</td>', 'A nice winterly scene, but I wish it was larger. If you have PS you can look at this tutorial to get your image up to 640 pixels and 150 kb. Your image is 82 kb, which means you could get twice as many fine details smoothed out in the cattails. Hope this helps, I like your image, just a little small.', '2007-12-04 17:35:34.000000', NULL, 1),
(4288892, 616376, 22301, '<td valign="top">nice match for the challenge, but not exciting enough for many voters to get the highest score. Maybe if you tried lighting this from the side it could have created more interest.</td>', 'nice match for the challenge, but not exciting enough for many voters to get the highest score. Maybe if you tried lighting this from the side it could have created more interest.', '2007-12-04 17:37:46.000000', NULL, 1),
(4288896, 616272, 22301, '<td valign="top">very nice, an interesting placement of the leaf in the frame but it works for me.</td>', 'very nice, an interesting placement of the leaf in the frame but it works for me.', '2007-12-04 17:39:03.000000', NULL, 1),
(4288907, 617022, 22301, '<td valign="top">I like this image, especially those shoes, modern day Dorothy. :)<br/>But I don''t see a crowd.<br/>You may want to look at this <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a> so you can get your images up to 640 pixels and 150 kb. It shows you how to use the Save for Web function for photoshop and will allow you to make your photo up to the full size.</td>', 'I like this image, especially those shoes, modern day Dorothy. :)But I don''t see a crowd.You may want to look at this tutorial so you can get your images up to 640 pixels and 150 kb. It shows you how to use the Save for Web function for photoshop and will allow you to make your photo up to the full size.', '2007-12-04 17:43:24.000000', NULL, 1),
(4288913, 615726, 22301, '<td valign="top">its hard for me to tell exactly who is the one that is alone. the lady standing is my guess, maybe she is going to meet the man in the bottom left, but I don''t see any room for her at the table. The black and white conversion is well done, just too subtle for me I think.</td>', 'its hard for me to tell exactly who is the one that is alone. the lady standing is my guess, maybe she is going to meet the man in the bottom left, but I don''t see any room for her at the table. The black and white conversion is well done, just too subtle for me I think.', '2007-12-04 17:46:40.000000', NULL, 1),
(4288914, 617501, 22301, '<td valign="top">excellent low light photo, it seems the light is shining just on them.</td>', 'excellent low light photo, it seems the light is shining just on them.', '2007-12-04 17:47:38.000000', NULL, 1),
(4288916, 617333, 22301, '<td valign="top">a nice idea, I can feel the crowd of cows out of the frame.</td>', 'a nice idea, I can feel the crowd of cows out of the frame.', '2007-12-04 17:48:34.000000', NULL, 1),
(4288917, 617409, 22301, '<td valign="top">I like the title to go with the alone theme of the challenge</td>', 'I like the title to go with the alone theme of the challenge', '2007-12-04 17:49:48.000000', NULL, 1),
(4288923, 616827, 22301, '<td valign="top">the shallow DoF is nice, so is the choice to go to black and white. 6</td>', 'the shallow DoF is nice, so is the choice to go to black and white. 6', '2007-12-04 17:51:40.000000', NULL, 1),
(4288939, 616182, 75733, '<td valign="top">Cool shot!  Nicely done!</td>', 'Cool shot!  Nicely done!', '2007-12-04 18:10:02.000000', NULL, 1),
(4288940, 617426, 75733, '<td valign="top">Love the contrast and the composition is simple.  Wonderful shot!</td>', 'Love the contrast and the composition is simple.  Wonderful shot!', '2007-12-04 18:10:05.000000', NULL, 1),
(4288949, 616035, 22301, '<td valign="top">You may want to look at this <a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a> if you have photoshop, it will help you get your images up to the 150 kb by using the Save for Web feature. It gets rid of the of the exif data which eats up space. If you were to right click this and save it then open it and look at its properties it would have all the details of your camera settings and that you used ACD software. I have that to and I don''t think you can adjust the settings like in other softwares. I think the image works well, and I think performing for a crowd is the most easily identifiable alone in a crowd scenario.</td>', 'You may want to look at this tutorial if you have photoshop, it will help you get your images up to the 150 kb by using the Save for Web feature. It gets rid of the of the exif data which eats up space. If you were to right click this and save it then open it and look at its properties it would have all the details of your camera settings and that you used ACD software. I have that to and I don''t think you can adjust the settings like in other softwares. I think the image works well, and I think performing for a crowd is the most easily identifiable alone in a crowd scenario.', '2007-12-04 18:15:54.000000', NULL, 1),
